<template>
  <div class="tr-step" :class="{ 'tr-step--open': open }" :data-test="'tr-step-' + index">
    <!-- Head: index, verb, action key, the value AFTER this step, tools. -->
    <div class="tr-step-head" @click="$emit('toggle')">
      <span class="tr-step-idx">{{ index + 1 }}</span>
      <span class="tr-step-verb">{{ $t(meta.verbKey) }}</span>
      <span class="tr-step-type">{{ action.type }}</span>
      <q-space />
      <span v-if="result !== ''" class="tr-step-res" :title="result">
        {{ result }}
      </span>
      <span v-if="!readonly" class="tr-step-tools" @click.stop>
        <q-btn
          flat dense round size="sm" icon="keyboard_arrow_up"
          :disable="index === 0"
          :aria-label="$t('move_up')"
          @click="$emit('move', -1)"
        />
        <q-btn
          flat dense round size="sm" icon="keyboard_arrow_down"
          :disable="index === total - 1"
          :aria-label="$t('move_down')"
          @click="$emit('move', 1)"
        />
        <q-btn
          flat dense round size="sm" icon="close" color="negative"
          :aria-label="$t('remove')"
          @click="$emit('remove')"
        />
      </span>
      <q-icon
        v-else
        :name="open ? 'expand_less' : 'expand_more'"
        size="18px"
        class="tr-step-chev"
      />
    </div>

    <!-- Body: the action's own params. -->
    <div v-if="open" class="tr-step-body">
      <!-- clear takes no options at all. -->
      <p v-if="action.type === 'clear'" class="tr-step-note">{{ $t('clear_action_note') }}</p>
      <p v-if="action.type === 'clear_rows'" class="tr-step-note">{{ $t('clear_rows_action_note') }}</p>

      <!-- value_map gets a from → to pair editor ahead of its flat params. -->
      <div v-if="action.type === 'value_map'" class="tr-param tr-param--wide">
        <label class="rb-label">{{ $t('mappings_from_to') }}</label>
        <div class="tr-mapgrid">
          <div v-for="(pair, mi) in mapPairs" :key="mi" class="tr-maprow">
            <q-input
              outlined dense class="back-white rb-mono"
              :model-value="pair[0]"
              :placeholder="$t('map_from')"
              :readonly="readonly"
              @update:model-value="(val) => setPair(mi, 0, val)"
            />
            <span class="tr-map-arrow">→</span>
            <q-input
              outlined dense class="back-white rb-mono"
              :model-value="pair[1]"
              :placeholder="$t('map_to')"
              :readonly="readonly"
              @update:model-value="(val) => setPair(mi, 1, val)"
            />
            <q-btn
              v-if="!readonly"
              flat dense round size="sm" icon="close"
              :aria-label="$t('remove')"
              @click="removePair(mi)"
            />
            <span v-else aria-hidden="true" />
          </div>
          <button v-if="!readonly" type="button" class="tr-link-add" @click="addPair">
            + {{ $t('add_mapping') }}
          </button>
        </div>
      </div>

      <!-- Flat params, laid out in a wrapping grid. -->
      <div class="tr-params">
        <div
          v-for="spec in specs"
          :key="spec.k"
          class="tr-param"
          :class="{ 'tr-param--wide': spec.wide }"
        >
          <!-- A toggle carries its label inline, so it skips the caption above. -->
          <template v-if="spec.type === 'toggle'">
            <q-checkbox
              :model-value="!!params[spec.k]"
              :label="$t(spec.labelKey)"
              :disable="readonly"
              dense
              @update:model-value="(val) => setParam(spec, val)"
            />
          </template>
          <template v-else>
            <label class="rb-label">{{ $t(spec.labelKey) }}</label>
            <q-select
              v-if="spec.type === 'select'"
              outlined dense emit-value map-options
              class="back-white"
              :model-value="params[spec.k]"
              :options="selectOptions(spec)"
              :readonly="readonly"
              @update:model-value="(val) => setParam(spec, val)"
            />
            <q-input
              v-else
              outlined dense
              class="back-white rb-mono"
              :type="spec.type === 'number' ? 'number' : 'text'"
              :model-value="inputValue(spec)"
              :min="spec.min"
              :maxlength="spec.maxlen"
              :placeholder="spec.phKey ? $t(spec.phKey) : ''"
              :readonly="readonly"
              @update:model-value="(val) => setParam(spec, val)"
            />
          </template>
        </div>
      </div>

      <!-- add_row: one line per column the new row sets. Each takes either a
           fixed value or a field read off the document; columns left out of
           the list stay empty on the new row. -->
      <div v-if="action.type === 'add_row'" class="tr-param tr-param--wide">
        <label class="rb-label">{{ $t('column_values_for_the_new_row') }}</label>
        <div class="tr-rowvals">
          <div v-for="(rv, vi) in rowVals" :key="vi" class="tr-rowval" :data-test="'tr-rowval-' + vi">
            <q-select
              outlined dense emit-value map-options
              class="back-white rb-mono"
              :model-value="rv.col"
              :options="columnSelectOptions(rv.col)"
              :readonly="readonly"
              :placeholder="rv.col ? '' : $t('select_column')"
              @update:model-value="(val) => setRowValue(vi, { col: String(val ?? '') })"
            />
            <span class="tr-rowval-eq">=</span>
            <q-btn-toggle
              :model-value="rv.from"
              :options="fromOptions"
              no-caps unelevated dense
              class="tr-rowval-from"
              toggle-color="primary"
              color="white"
              text-color="grey-8"
              :disable="readonly"
              @update:model-value="(val) => setRowValueMode(vi, val)"
            />
            <q-select
              v-if="rv.from === 'field'"
              outlined dense emit-value map-options use-input input-debounce="0"
              class="back-white rb-mono"
              :model-value="rv.value"
              :options="rowSourceOptionsFor(vi)"
              :readonly="readonly"
              :placeholder="rv.value ? '' : $t('select_field')"
              popup-content-class="rb-field-popup"
              @filter="(val, update) => onRowSourceFilter(vi, val, update)"
              @update:model-value="(val) => setRowValue(vi, { value: String(val ?? '') })"
            >
              <!-- Same grouped rendering as the condition and read-from pickers:
                   one keyed root per option with the section label nested inside
                   it, shown on the first option of each group so it cannot
                   duplicate as the list scrolls. -->
              <template #option="scope">
                <div :key="scope.opt.value">
                  <div
                    v-if="scope.opt.group && scope.opt.group !== rowSourceOptionsFor(vi)[scope.index - 1]?.group"
                    class="rb-opt-group"
                    :class="{ 'rb-opt-group--first': scope.index === 0 }"
                  >{{ scope.opt.group }}</div>
                  <q-item v-bind="scope.itemProps"><q-item-section>{{ scope.opt.label }}</q-item-section></q-item>
                </div>
              </template>
            </q-select>
            <q-input
              v-else
              outlined dense
              class="back-white rb-mono"
              :model-value="rv.value"
              :placeholder="$t('fixed_value')"
              :readonly="readonly"
              @update:model-value="(val) => setRowValue(vi, { value: String(val ?? '') })"
            />
            <q-btn
              v-if="!readonly"
              flat dense round size="sm" icon="close"
              :aria-label="$t('remove')"
              :data-test="'tr-rowval-remove-' + vi"
              @click="removeRowValue(vi)"
            />
            <span v-else aria-hidden="true" />
          </div>
          <button
            v-if="!readonly"
            type="button"
            class="tr-link-add"
            data-test="tr-rowval-add"
            @click="addRowValue"
          >
            + {{ $t('add_column') }}
          </button>
        </div>
        <span class="tr-step-hint">{{ $t('row_values_hint') }}</span>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { PropType } from 'vue';
import {
  actionMeta,
  paramsFor,
  rowValues,
  newRowValue,
  type ActionMeta,
  type ParamSpec,
  type FieldOption,
  type RowValue,
} from './transformation-rule-model';
import type { TransformationAction } from 'src/services/settings/TransformationRulesApiService';

export default defineComponent({
  name: 'TransformationStepCard',
  props: {
    action: {
      type: Object as PropType<TransformationAction>,
      required: true,
    },
    index: {
      type: Number,
      required: true,
    },
    total: {
      type: Number,
      required: true,
    },
    open: {
      type: Boolean,
      default: false,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    // The pipeline value AFTER this step, shown as a chip in the head.
    result: {
      type: String,
      default: '',
    },
    // Sub-organisation options, needed for the set_value picker.
    subOrgOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
    // Bare column names of the rule's table — the columns an added row can set.
    columnOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
    // Namespaced fields an added row can copy a value FROM (header / doc).
    rowSourceOptions: {
      type: Array as PropType<FieldOption[]>,
      default: () => [],
    },
  },
  emits: ['toggle', 'move', 'remove', 'change'],
  data() {
    return {
      // Per-line filtered copies of the row-source list, keyed by row-value
      // index, so typing in one line's field picker never disturbs another's.
      localRowSourceOptions: {} as Record<number, FieldOption[]>,
    };
  },
  computed: {
    meta(): ActionMeta {
      // Every rendered step has a catalogue entry; fall back to a bare shape so
      // an unknown action type from the backend still renders its head.
      return (
        actionMeta(this.action.type) || {
          verbKey: this.action.type,
          icon: '?',
          hintKey: '',
          groupKey: '',
          params: [],
          def: {},
        }
      );
    },
    params(): Record<string, unknown> {
      return (this.action.params || {}) as Record<string, unknown>;
    },
    specs(): ParamSpec[] {
      return paramsFor(this.action, this.subOrgOptions);
    },
    mapPairs(): [string, string][] {
      return (this.params.pairs as [string, string][]) || [];
    },
    rowVals(): RowValue[] {
      return rowValues(this.action);
    },
    fromOptions(): { label: string; value: RowValue['from'] }[] {
      return [
        { label: this.$t('value'), value: 'static' },
        { label: this.$t('field'), value: 'field' },
      ];
    },
  },
  methods: {
    // Params are stored loosely (the backend takes a free-form object), so
    // narrow one to what a q-input can bind. An intentionally blank optional
    // number stays '' rather than becoming 0.
    inputValue(spec: ParamSpec): string | number {
      const raw = this.params[spec.k];
      if (raw === null || raw === undefined) return '';
      return typeof raw === 'number' ? raw : String(raw);
    },
    // Option list for a select param. `optLabelKeys` are translated; `optLabels`
    // are literal (patterns, locale codes, sub-org names).
    selectOptions(spec: ParamSpec): { label: string; value: string }[] {
      const opts = spec.opts || [];
      return opts.map((value, i) => {
        let label = value;
        if (spec.optLabelKeys && spec.optLabelKeys[i]) label = this.$t(spec.optLabelKeys[i]);
        else if (spec.optLabels && spec.optLabels[i]) label = spec.optLabels[i];
        return { label, value };
      });
    },
    // Write one param back. Numbers keep '' (an intentionally blank optional)
    // rather than coercing to 0, which the serializer then omits.
    setParam(spec: ParamSpec, raw: unknown) {
      let value: unknown = raw;
      if (spec.type === 'number') {
        value = raw === '' || raw === null ? '' : Number(raw);
      } else if (spec.type === 'toggle') {
        value = !!raw;
      } else {
        value = raw ?? '';
      }
      this.$emit('change', { key: spec.k, value, struct: !!spec.struct });
    },
    // Mutate a COPY of the pair list and emit it — the parent owns the action,
    // so the child never writes through its own prop.
    editPairs(mutate: (pairs: [string, string][]) => void) {
      const pairs = this.mapPairs.map((p) => [p[0], p[1]] as [string, string]);
      mutate(pairs);
      // Always leave one editable row so the grid never collapses to nothing.
      if (!pairs.length) pairs.push(['', '']);
      this.$emit('change', { key: 'pairs', value: pairs });
    },
    setPair(mi: number, side: 0 | 1, raw: unknown) {
      this.editPairs((pairs) => {
        if (pairs[mi]) pairs[mi][side] = String(raw ?? '');
      });
    },
    addPair() {
      this.editPairs((pairs) => pairs.push(['', '']));
    },
    removePair(mi: number) {
      this.editPairs((pairs) => pairs.splice(mi, 1));
    },
    // Column list for one row-value line. A column already assigned by another
    // line is disabled rather than hidden, so the list stays in a stable order.
    // A column the rule references but the table no longer has is kept as its
    // own option, else opening the rule would silently blank the assignment.
    columnSelectOptions(current: string): { label: string; value: string; disable?: boolean }[] {
      const taken = this.rowVals.map((v) => v.col);
      const known = this.columnOptions.map((c) => c.value);
      const opts = this.columnOptions.map((c) => ({
        label: c.label,
        value: c.value,
        disable: c.value !== current && taken.includes(c.value),
      }));
      if (current && !known.includes(current)) {
        opts.unshift({ label: current, value: current, disable: false });
      }
      return opts;
    },
    // This line's field list: its own filtered copy once the user has typed,
    // otherwise the shared source.
    rowSourceOptionsFor(vi: number): FieldOption[] {
      return this.localRowSourceOptions[vi] || this.rowSourceOptions;
    },
    // Filter one line's list locally against the shared source. Always a fresh
    // array so the bound options never accumulate across cycles.
    onRowSourceFilter(vi: number, val: string, update: (cb: () => void) => void) {
      update(() => {
        const needle = val.toLowerCase();
        this.localRowSourceOptions[vi] = needle
          ? this.rowSourceOptions.filter(
              (f) =>
                f.label.toLowerCase().includes(needle) || f.value.toLowerCase().includes(needle),
            )
          : this.rowSourceOptions.slice();
      });
    },
    // Same contract as editPairs: mutate a COPY and emit it, never write
    // through the action prop the parent owns.
    editRowValues(mutate: (values: RowValue[]) => void) {
      const values = this.rowVals.map((v) => ({ ...v }));
      mutate(values);
      if (!values.length) values.push(newRowValue());
      this.$emit('change', { key: 'values', value: values });
    },
    setRowValue(vi: number, patch: Partial<RowValue>) {
      this.editRowValues((values) => {
        if (values[vi]) values[vi] = { ...values[vi], ...patch };
      });
    },
    // Switching between a fixed value and a field reference clears the value:
    // a literal is not a valid field path and vice versa.
    setRowValueMode(vi: number, mode: unknown) {
      const from: RowValue['from'] = mode === 'field' ? 'field' : 'static';
      if (this.rowVals[vi]?.from === from) return;
      this.setRowValue(vi, { from, value: '' });
    },
    addRowValue() {
      // Pre-pick the first column that is still free, so the new line is usable
      // without opening the picker.
      const taken = this.rowVals.map((v) => v.col);
      const next = this.columnOptions.find((c) => !taken.includes(c.value));
      this.editRowValues((values) => values.push(newRowValue(next ? next.value : '')));
    },
    removeRowValue(vi: number) {
      this.editRowValues((values) => values.splice(vi, 1));
      // Line indices shift after a splice, so a kept filter copy would attach
      // to the wrong line — reset and let each fall back to the full list.
      this.localRowSourceOptions = {};
    },
  },
});
</script>

