  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--muted);
  border: 1px solid var(--border);
  font-size: 0.6875rem;
  font-weight: 700;
  color: var(--muted-foreground);
}

.tr-step-verb {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--foreground);
}

// The raw action key, shown quietly beside the verb so power users can map the
// UI onto the stored JSON.
.tr-step-type {
  font-family: 'Roboto Mono', ui-monospace, monospace;
  font-size: 0.6875rem;
  color: var(--muted-foreground);
}

